import{_ as e,o as a,c as d,a3 as r}from"./chunks/framework.BTt0kA_k.js";const b=JSON.parse('{"title":"数据存储与升级机制","description":"","frontmatter":{},"headers":[],"relativePath":"developer/data-and-upgrade.md","filePath":"developer/data-and-upgrade.md"}'),o={name:"developer/data-and-upgrade.md"};function c(n,t,s,i,p,l){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="数据存储与升级机制" tabindex="-1">数据存储与升级机制 <a class="header-anchor" href="#数据存储与升级机制" aria-label="Permalink to &quot;数据存储与升级机制&quot;">​</a></h1><h2 id="持久化与凭据" tabindex="-1">持久化与凭据 <a class="header-anchor" href="#持久化与凭据" aria-label="Permalink to &quot;持久化与凭据&quot;">​</a></h2><p>应用数据根目录由应用身份决定，路径见<a href="./build-and-environments.html#两套应用身份">环境隔离表</a>。</p><table tabindex="0"><thead><tr><th>内容</th><th>存储位置或机制</th></tr></thead><tbody><tr><td>站点、模型、设置、健康状态与记录摘要</td><td>应用数据目录中的 <code>relaypulse.sqlite3</code></td></tr><tr><td>站点访问凭据</td><td>SQLite 的 <code>site_credentials</code> 表</td></tr><tr><td>正式探测请求与响应过程</td><td><code>probe-records/</code></td></tr><tr><td>IQ 测试原始流和产物</td><td><code>iq-test/</code></td></tr></tbody></table><p>凭据当前没有应用层加密，也未接入系统钥匙串。站点读取接口只返回是否配置凭据，不返回原密钥。Unix 平台将应用数据根目录权限设为 <code>0700</code>，数据库文件设为 <code>0600</code>；实现位于 <code>backend/crates/storage/src/shared/persistence/</code>。</p><p>原始响应、模型输出和完整数据库可能含敏感内容。开发夹具应使用独立测试数据；处理故障材料时，核对日志脱敏与诊断包导出范围。</p><h2 id="记录与诊断边界" tabindex="-1">记录与诊断边界 <a class="header-anchor" href="#记录与诊断边界" aria-label="Permalink to &quot;记录与诊断边界&quot;">​</a></h2><p>正式探测过程文件随历史保留策略或手动清理处理，草稿试探不写入正式历史。诊断日志和诊断包使用独立脱敏与保留规则，正式探测响应文件不混入诊断包。</p><p>Token 统计保留供应商实际上报的数据。缺失字段保持为空，不从输出文本估算。</p><h2 id="启动迁移入口" tabindex="-1">启动迁移入口 <a class="header-anchor" href="#启动迁移入口" aria-label="Permalink to &quot;启动迁移入口&quot;">​</a></h2><p>3.0.1 的旧数据识别、恢复和激活由以下位置协作完成：</p><table tabindex="0"><thead><tr><th>位置</th><th>职责</th></tr></thead><tbody><tr><td><code>frontend/src/components/StartupGate.vue</code></td><td>展示启动检查、备份迁移、失败和重启状态</td></tr><tr><td><code>backend/src/application/startup_recovery.rs</code></td><td>启动恢复与迁移协调</td></tr><tr><td><code>backend/src/application/startup_recovery/activation.rs</code></td><td>转换后的数据激活与恢复</td></tr><tr><td><code>backend/src/application/data_transfer/</code></td><td>离线转换、证据校验与报告</td></tr></tbody></table><p>只有识别到受支持的旧数据格式时，界面才提供迁移。转换或校验失败会阻止进入业务页面，应保留源目录和错误用于排查。</p><h2 id="离线转换工具" tabindex="-1">离线转换工具 <a class="header-anchor" href="#离线转换工具" aria-label="Permalink to &quot;离线转换工具&quot;">​</a></h2><p><code>relaypulse-data-transfer</code> 是开发维护工具，命令行参数为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>relaypulse-data-transfer --offline-source STOPPED_SOURCE_DIR --destination NEW_DIR</span></span></code></pre></div><p>调用前必须停止源应用及其他文件写入者；目标必须是尚不存在的独立目录，父目录已存在，且源、目标不能相互包含。工具保留源文件，在目标生成一致性备份、转换数据和校验报告。</p><p>转换中以 <code>conversion-incomplete</code> 标记未完成状态，成功后写入 <code>conversion-verification.json</code> 并移除未完成标记。退出失败或缺少成功校验报告时，不应激活目标目录。工具自身不切换应用使用的数据目录。</p><p>修改存储格式或恢复逻辑时，应覆盖 <code>backend/tests/integration/data_transfer/</code>、<code>backend/tests/integration/startup/</code> 中受影响的转换、拒绝和恢复场景，并单独验证桌面启动提示。</p>',19)])])}const u=e(o,[["render",c]]);export{b as __pageData,u as default};
